"use client";
import * as React from 'react';
import {CourseParticipantFields,emptyParticipant,type ParticipantInput} from '@/app/_components/course-participant-fields';
export function PublicCourseRegistration({token}:{token:string}){
 const [rows,setRows]=React.useState([{id:1,...emptyParticipant}]),[nextId,setNextId]=React.useState(2),[busy,setBusy]=React.useState(false),[error,setError]=React.useState(''),[success,setSuccess]=React.useState(false),[allowed,setAllowed]=React.useState(false),[website,setWebsite]=React.useState('');
 async function submit(event:React.FormEvent){event.preventDefault();if(busy)return;setBusy(true);setError('');setSuccess(false);try{const response=await fetch('/api/public/courses/'+token,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({participants:rows.map(({firstName,lastName,dateOfBirth})=>({firstName,lastName,dateOfBirth})),website})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Speichern fehlgeschlagen.');setSuccess(true);setRows([{id:nextId,...emptyParticipant}]);setNextId(value=>value+1);setAllowed(false);}catch(error){setError(error instanceof Error?error.message:'Bitte prüfen Sie die Verbindung und versuchen Sie es erneut.');}finally{setBusy(false);}}
 return <form onSubmit={submit} className="space-y-5 rounded-3xl border border-[var(--border)] bg-[var(--surface)] p-5 shadow-[var(--shadow)] sm:p-8"><h2 className="text-lg font-bold">Teilnehmer eintragen</h2>{error?<p role="alert" className="rounded-xl bg-red-50 p-4 text-sm text-red-800">{error}</p>:null}{success?<p role="status" className="rounded-xl bg-emerald-50 p-4 text-sm text-emerald-900">Die Teilnehmerdaten wurden gespeichert. Bei unveränderten Wiederholungen entstehen keine doppelten Einträge. Sie können weitere Personen erfassen.</p>:null}<fieldset disabled={busy} className="min-w-0 space-y-4">{rows.map((row,index)=><div key={row.id} className="space-y-3 rounded-xl border border-[var(--border)] bg-[var(--surface-2)] p-4"><div className="flex flex-wrap items-center justify-between gap-2"><h3 className="text-sm font-semibold">Teilnehmer {index+1}</h3>{rows.length>1?<button type="button" className="ui-button-secondary" onClick={()=>setRows(current=>current.filter(person=>person.id!==row.id))}>Entfernen</button>:null}</div><CourseParticipantFields value={row} onChange={(value:ParticipantInput)=>setRows(current=>current.map(person=>person.id===row.id?{...person,...value}:person))}/></div>)}<button type="button" className="ui-button-secondary" disabled={rows.length>=20} onClick={()=>{setRows(current=>[...current,{id:nextId,...emptyParticipant}]);setNextId(value=>value+1);}}>+ Weitere Person</button><label className="flex items-start gap-3 text-sm"><input type="checkbox" required checked={allowed} onChange={event=>setAllowed(event.target.checked)} className="mt-1"/>Ich bin berechtigt, diese Teilnehmerdaten für die Kursorganisation und Teilnahmebescheinigungen zu übermitteln.</label><div aria-hidden="true" className="hidden"><label>Website<input tabIndex={-1} autoComplete="off" value={website} onChange={event=>setWebsite(event.target.value)}/></label></div><button className="ui-button-primary" disabled={!allowed}>{busy?'Wird gespeichert …':'Teilnehmerdaten speichern'}</button></fieldset><p className="text-xs text-[color:var(--muted)]">Übermitteln Sie nur Daten der für diesen Kurs vorgesehenen Personen. Der Veranstalter verwendet die Angaben für Teilnehmerverwaltung, Anwesenheitskontrolle und Bescheinigungen. Bewahren Sie diesen Link vertraulich auf.</p></form>;
}
